#!/usr/bin/env python3
"""统计 CSV 文件每一列的非空值数量。"""

import csv
import sys
from collections import Counter


def count_nonempty(path):
    counts = Counter()
    names = []
    with open(path, newline="", encoding="utf-8-sig") as f:
        reader = csv.reader(f)
        try:
            names = next(reader)
        except StopIteration:
            return names, counts

        for i, name in enumerate(names):
            counts[i] = 0

        for row in reader:
            for i, value in enumerate(row):
                if i not in counts:
                    names.append(f"column_{i + 1}")
                    counts[i] = 0
                if value.strip():
                    counts[i] += 1

    return names, counts


def main(argv):
    if len(argv) != 2:
        print(f"用法: {argv[0]} <csv 文件>", file=sys.stderr)
        return 1

    try:
        names, counts = count_nonempty(argv[1])
    except OSError as exc:
        print(f"无法读取文件: {exc}", file=sys.stderr)
        return 1

    width = max((len(n) for n in names), default=0)
    for i, name in enumerate(names):
        print(f"{name.ljust(width)}\t{counts[i]}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
